param([string]$RunDate='PLAN-DATE',[ValidateSet('PLAN','EXECUTE')][string]$ExecutionMode='PLAN')
$ErrorActionPreference='Stop';$root=(Resolve-Path (Join-Path $PSScriptRoot '..\..')).Path;$runner=Join-Path $PSScriptRoot 'run-experiment-1-21-core.ps1';$planRoot=Join-Path $root 'backend\experiments\results\experiment-1-21\plan';$coreRoot=Join-Path $root 'backend\experiments\results\experiment-1-21\core';$runs=@(@{c='BASELINE';i='001'},@{c='REMEDIATION';i='001'},@{c='BASELINE';i='002'},@{c='REMEDIATION';i='002'},@{c='BASELINE';i='003'},@{c='REMEDIATION';i='003'})
if($ExecutionMode-eq'EXECUTE' -and $RunDate-notmatch '^\d{8}$'){throw 'EXECUTE requires -RunDate YYYYMMDD'};New-Item -ItemType Directory -Force -Path $planRoot|Out-Null;$started=@();$failure=$null
foreach($r in $runs){try{& powershell.exe -NoProfile -ExecutionPolicy Bypass -File $runner -Condition $r.c -RunIndex $r.i -RunDate $RunDate -ExecutionMode $ExecutionMode;if($LASTEXITCODE){throw "core exit $LASTEXITCODE"};$started+="$($r.c)-$($r.i)"}catch{$failure=$_;break}}
$states=@();foreach($r in $runs){$id="RUN-$RunDate-EXP121-$($r.c)-$($r.i)";$dir=Join-Path $coreRoot $id;$complete=Test-Path (Join-Path $dir 'COMPLETED');$failed=Test-Path (Join-Path $dir 'EXECUTION_FAILED');$states+=[ordered]@{runId=$id;started=(Test-Path $dir);completed=$complete;failed=$failed;warmupInvoked=(Test-Path (Join-Path $root "experiment\results\SMOKE-$RunDate-EXP121-$($r.c)-$($r.i)"));coreInvoked=(Test-Path (Join-Path $root "experiment\results\$id"))}}
$ledger=[ordered]@{experiment='Experiment 1-21';executionMode=$ExecutionMode;runDate=$RunDate;requestedRuns=@($runs|ForEach-Object{"$($_.c)-$($_.i)"});startedRuns=@($states|Where-Object started).Count;completedRuns=@($states|Where-Object completed).Count;failedRuns=@($states|Where-Object failed).Count;notStartedRuns=@($states|Where-Object{-not $_.started}|ForEach-Object runId);warmupInvocations=@($states|Where-Object warmupInvoked).Count;coreInvocations=@($states|Where-Object coreInvoked).Count;executionStatus=if($ExecutionMode-eq'PLAN'){'NOT_RUN'}elseif($failure){'FAILED'}elseif((@($states|Where-Object completed).Count)-eq 6){'COMPLETED'}else{'INCOMPLETE'};stoppedAfterRun=if($failure){$states|Where-Object failed|Select-Object -First 1 -ExpandProperty runId}else{$null};runStates=$states};$ledger|ConvertTo-Json -Depth 8|Set-Content (Join-Path $planRoot 'runner-readiness.json') -Encoding UTF8
if($failure){throw $failure}

